import React from 'react';
import data from './../data/experienceData.js';
import { FaBriefcase, FaMapMarkerAlt, FaCalendarAlt, FaTrophy, FaCode } from 'react-icons/fa';

function Experience() {
  return (
    <section id="experience" className='py-20 px-6 sm:px-8 lg:px-12 bg-gradient-to-br from-[#1a1f26] to-[#20262E]'>
      <div className="max-w-7xl mx-auto">
        {/* Section Header */}
        <div className="text-center mb-16">
          <h2 className="text-4xl sm:text-5xl md:text-6xl font-bold text-white mb-6">
            My <span className="text-[#6699CC]">Experience</span>
          </h2>
          <div className="w-24 h-1 bg-[#6699CC] mx-auto rounded-full mb-8"></div>
          <p className="text-gray-300 text-xl max-w-3xl mx-auto leading-relaxed">
            My professional journey and the impact I've made at each step
          </p>
        </div>

        {/* Timeline */}
        <div className="relative">
          {/* Center timeline for larger screens */}
          <div className="hidden md:block absolute left-1/2 top-0 transform -translate-x-1/2 h-full w-1">
            <div className="h-full w-full bg-gradient-to-b from-[#6699CC] to-transparent opacity-40"></div>
          </div>

          {data.map((exp, index) => (
            <EnhancedExperienceCard key={exp.id} experience={exp} index={index} />
          ))}
        </div>
      </div>
    </section>
  );
}

// Enhanced Experience Card Component
function EnhancedExperienceCard({ experience, index }) {
  const isEven = index % 2 === 0;
  const sideClass = isEven ? 'md:justify-start md:pl-0' : 'md:justify-end md:pr-0';
  const animateClass = isEven ? 'animate-fade-in-left' : 'animate-fade-in-right';

  return (
    <div className={`relative mb-12 md:mb-20 flex items-start ${sideClass}`}>
      {/* Center timeline dot */}
      <div className="md:absolute md:left-1/2 md:transform md:-translate-x-1/2 md:top-6 flex flex-col items-center">
        <div className="w-6 h-6 rounded-full bg-gradient-to-r from-[#6699CC] to-[#58A6FF] border-4 border-[#0D1117] shadow-elegant"></div>
        <div className="hidden md:block w-px h-full bg-gradient-to-b from-[#6699CC] to-transparent mt-2 opacity-30"></div>
      </div>

      {/* Card container aligned left or right on larger screens */}
      <div className={`relative z-10 w-full md:w-5/12 ${isEven ? 'md:mr-auto md:text-right' : 'md:ml-auto md:text-left'}`}>
        <div className={`card-hover glass-effect p-6 rounded-2xl border border-gray-700/40 ${animateClass}`}>
          {/* Header */}
          <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-4">
            <div className="mb-3 md:mb-0">
              <h3 className="text-2xl font-bold text-white group-hover:text-gradient transition-colors duration-300">{experience.title}</h3>
              <div className="flex items-center justify-start md:justify-end space-x-2 mt-2">
                <FaBriefcase className="text-[#6699CC]" />
                <span className="text-[#6699CC] font-semibold">{experience.org}</span>
              </div>
            </div>

            <div className="flex flex-col items-start md:items-end space-y-2">
              <div className="flex items-center space-x-2">
                <FaCalendarAlt className="text-gray-400" />
                <span className="text-gray-300">{experience.date}</span>
              </div>
              <div className="flex items-center space-x-2">
                <FaMapMarkerAlt className="text-gray-400" />
                <span className="text-gray-300">{experience.location}</span>
              </div>
              <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                experience.type === 'Full-time' ? 'bg-green-500/20 text-green-400' :
                experience.type === 'Internship' ? 'bg-blue-500/20 text-blue-400' :
                'bg-purple-500/20 text-purple-400'
              }`}>{experience.type}</span>
            </div>
          </div>

          <p className="text-gray-300 text-base mb-4 leading-relaxed">{experience.description}</p>

          {/* Responsibilities */}
          <div className="mb-4">
            <h4 className="text-lg font-semibold text-white mb-2">Key Responsibilities:</h4>
            <ul className="space-y-2">
              {experience.responsibilities.map((resp, idx) => (
                <li key={idx} className="flex items-start gap-3">
                  <span className="w-2 h-2 bg-[#6699CC] rounded-full mt-2 flex-shrink-0"></span>
                  <span className="text-gray-300">{resp}</span>
                </li>
              ))}
            </ul>
          </div>

          {/* Achievements */}
          <div className="mb-4">
            <h4 className="text-lg font-semibold text-white mb-2 flex items-center gap-2"><FaTrophy className="text-[#6699CC]" /> Key Achievements:</h4>
            <ul className="space-y-2">
              {experience.achievements.map((achievement, idx) => (
                <li key={idx} className="flex items-start gap-3">
                  <span className="w-2 h-2 bg-green-400 rounded-full mt-2 flex-shrink-0"></span>
                  <span className="text-gray-300">{achievement}</span>
                </li>
              ))}
            </ul>
          </div>

          {/* Technologies */}
          <div>
            <h4 className="text-lg font-semibold text-white mb-2 flex items-center gap-2"><FaCode className="text-[#6699CC]" /> Technologies Used:</h4>
            <div className="flex flex-wrap gap-2">
              {experience.technologies.map((tech, idx) => (
                <span key={idx} className="px-3 py-1 bg-[#6699CC]/10 text-[#6699CC] rounded-full text-sm">{tech}</span>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Experience;
